/**
 * One turn of a conversation (`design/components/chat-message.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/chat-message.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { Icon, claimSlot, resolveSlot, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/chat-message.module.css'
import Avatar from '../structure/Avatar'

export type ChatMessageStatus = NonNullable<ChatMessageProps['status']>

export type ChatRole = NonNullable<ChatMessageProps['role']>

export interface ChatMessageProps {
  /**
   * The hover row of `ghost/neutral/sm iconOnly` Buttons, such as copy, regenerate and helpful.
   */
  actions?: JSX.Element
  /**
   * The speaker's name, used as the article's accessible name and first in the meta row.
   */
  author: string
  /**
   * The speaker's picture, replaced by the reader's initials or the model's mark when absent.
   */
  avatar?: string
  /**
   * The turn's content, in reading order.
   */
  children: JSX.Element
  /**
   * The speaker's role, which sets the layout and is the only frame choice the caller makes.
   */
  role: 'user' | 'system' | 'assistant'
  /**
   * The turn's status, where `complete` is the rest state and sets no attribute.
   */
  status?: 'error' | 'streaming' | 'complete' | 'stopped'
  /**
   * The app's text for `stopped` or `error`, such as "Stopped" or "Something went wrong".
   */
  statusMessage?: string
  /**
   * The time, preformatted by the app (Timeline's rule for time).
   */
  time?: string
}

/** One turn of a conversation. */
export default function ChatMessage(given: ChatMessageProps): JSX.Element {
  const props = mergeProps(
    { status: 'complete' } as Defaults<ChatMessageProps, 'status'>,
    claimSlot(given),
  )
  return scope(() => {
    const actionsSlot = resolveSlot(() => props.actions)
    return (
      <article
        class={styles.message}
        data-role={props.role}
        data-status={props.status === 'complete' ? undefined : props.status}
        aria-label={props.author}
        aria-busy={props.status === 'streaming' ? true : undefined}
        data-member="chat-message"
      >
        {props.role !== 'system' ? (
          <span class={styles.mark}>
            {props.role === 'assistant' && props.avatar === undefined ? (
              <span class={styles.model} aria-hidden="true">
                <Icon name="model" size="sm" />
              </span>
            ) : (
              <Avatar name={props.author} src={props.avatar} size="md" />
            )}
          </span>
        ) : null}
        {/* body */}
        <div class={styles.body}>
          {props.role !== 'system' ? (
            <div class={styles.meta}>
              {/* author */}
              <span class={styles.author}>{props.author}</span>
              {props.time !== undefined ? <span class={styles.time}>{props.time}</span> : null}
            </div>
          ) : null}
          {/* content */}
          <div class={styles.content}>{props.children}</div>
          {(props.status === 'stopped' || props.status === 'error') &&
          props.statusMessage !== undefined ? (
            <p class={styles.notice}>
              {/* noticeGlyph */}
              <span class={styles.noticeGlyph}>
                <Icon name={props.status === 'error' ? 'error' : 'warning'} size="sm" />
              </span>
              {props.statusMessage}
            </p>
          ) : null}
          {actionsSlot.filled() ? <div class={styles.actions}>{actionsSlot()}</div> : null}
        </div>
      </article>
    )
  })
}
